 "content": "from collections import Counter


def transform(grid):
    h, w = len(grid), len(grid[0])
    counts = Counter(v for row in grid for v in row)
    background = counts.most_common(1)[0][0]
    border = next((c for c, _ in counts.most_common() if c != background), background)
    out = [row[:] for row in grid]

    # Closed rectangular outlines are frames of the less-common color;
    # recolor their enclosed background cells.
    for top in range(h - 2):
        for bottom in range(top + 2, h):
            for left in range(w - 2):
                for right in range(left + 2, w):
                    if not all(grid[top][c] == border and grid[bottom][c] == border
                               for c in range(left, right + 1)):
                        continue
                    if not all(grid[r][left] == border and grid[r][right] == border
                               for r in range(top, bottom + 1)):
                        continue
                    if all(grid[r][c] == background
                           for r in range(top + 1, bottom)
                           for c in range(left + 1, right)):
                        for r in range(top + 1, bottom):
                            for c in range(left + 1, right):
                                out[r][c] = 4
    return out


